const body = $input.first().json.body || {};
const msg = body.message || {};
const from = msg.from || {};
const chat = msg.chat || {};
const text = msg.text || msg.caption || '';
let attachments = [];

if (msg.photo && msg.photo.length > 0) {
  const largest = msg.photo[msg.photo.length - 1];
  attachments.push({ type: 'image', url: 'https://api.telegram.org/file/bot' + ($env.TELEGRAM_BOT_TOKEN || '') + '/' + largest.file_id, mime_type: 'image/jpeg' });
}
if (msg.document) {
  attachments.push({ type: 'document', url: msg.document.file_id, mime_type: msg.document.mime_type || 'application/octet-stream' });
}
if (msg.voice) {
  attachments.push({ type: 'voice', url: msg.voice.file_id, mime_type: msg.voice.mime_type || 'audio/ogg' });
}

return [{
  json: {
    core_workflow_id: 'CUSTOMER_SERVICE_CORE_ID',
    channel: 'telegram',
    conversation_id: String(chat.id || ''),
    user_id: String(from.id || ''),
    message: text,
    attachments: attachments,
    metadata: {
      update_id: body.update_id || null,
      message_id: msg.message_id || null,
      username: from.username || null,
      first_name: from.first_name || null,
      chat_id: chat.id || null
    }
  }
}];

const inputItem = $input.first().json || {};
let rawText = String(inputItem.reply_text || '').trim();

// Remove accidental wrapper braces from serialized responses.
if (rawText.startsWith('{') && rawText.endsWith('}')) {
  const inner = rawText.slice(1, -1).trim();
  if (inner.length > 0) rawText = inner;
}

// Normalize WhatsApp-style list markers to Telegram-friendly bullets.
rawText = rawText
  .replace(/^\s*\*\s{2,}/gm, '• ')
  .replace(/^\s*\*\s+/gm, '• ')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

function splitByLimit(text, maxLen) {
  if (!text) return [];
  if (text.length <= maxLen) return [text];

  const parts = [];
  const paragraphs = text.split(/\n\n+/);
  let current = '';

  const flush = () => {
    if (current.trim()) parts.push(current.trim());
    current = '';
  };

  const forceSplit = (block) => {
    const lines = block.split('\n');
    let acc = '';

    const pushHard = (line) => {
      if (line.length <= maxLen) {
        if (!acc) acc = line;
        else if ((acc + '\n' + line).length <= maxLen) acc += '\n' + line;
        else {
          parts.push(acc.trim());
          acc = line;
        }
        return;
      }

      for (let i = 0; i < line.length; i += maxLen) {
        const chunk = line.slice(i, i + maxLen);
        if (acc && (acc + '\n' + chunk).length <= maxLen) acc += '\n' + chunk;
        else {
          if (acc.trim()) parts.push(acc.trim());
          acc = chunk;
        }
      }
    };

    for (const line of lines) pushHard(line);
    if (acc.trim()) parts.push(acc.trim());
  };

  for (const p of paragraphs) {
    const candidate = current ? `${current}\n\n${p}` : p;
    if (candidate.length <= maxLen) {
      current = candidate;
      continue;
    }

    if (current) flush();
    if (p.length <= maxLen) current = p;
    else forceSplit(p);
  }

  flush();
  return parts;
}

function toTelegramHtml(text) {
  const escaped = text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

  return escaped
    .replace(/\*\*(.+?)\*\*/g, '<b>$1</b>')
    .replace(/__([^_]+)__/g, '<b>$1</b>')
    .replace(/~~(.+?)~~/g, '<s>$1</s>')
    .replace(/\*([^*\n]+)\*/g, '<i>$1</i>')
    .replace(/_((?!_)[^_\n]+)_/g, '<i>$1</i>')
    .replace(/`([^`\n]+)`/g, '<code>$1</code>')
    .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2">$1</a>');
}

const derivedAttachmentUrl = String(inputItem.attachment_url || ((Array.isArray(inputItem.reply_attachments) ? (inputItem.reply_attachments[0] || {}).url : '') || '')).trim();
const derivedAttachmentCaption = String((Array.isArray(inputItem.reply_attachments) ? (inputItem.reply_attachments[0] || {}).caption : '') || inputItem.reply_text || 'Adjunto solicitado').trim();

const TELEGRAM_SAFE_LIMIT = 3900;
const chunks = splitByLimit(rawText, TELEGRAM_SAFE_LIMIT);

return chunks.map((chunk, idx) => ({
  json: {
    ...inputItem,
    telegram_text: toTelegramHtml(chunk),
    telegram_parse_mode: 'HTML',
    telegram_chunk_index: idx + 1,
    telegram_chunk_total: chunks.length,
    attachment_url: derivedAttachmentUrl,
    attachment_caption: derivedAttachmentCaption
  }
}));
